const KEY='aether.phase1.workspace.v1',$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],uid=()=>crypto.randomUUID?crypto.randomUUID():'aether-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const blank=()=>({profile:{name:'',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'',largeText:false,highContrast:false,reducedMotion:false,simpleMode:false},people:[],dates:[],reminders:[],memories:[],checkins:[],helpCards:[]});let data=read(),kind='',editing=null,timer;
