function renderPeople(){const q=($('#peopleSearch')?.value||'').toLowerCase(),c=$('#circleFilter')?.value||'',a=data.people.filter(x=>(!c||x.circle===c)&&[x.name,x.circle,x.relationship,x.email,x.phone,x.notes,x.supportNotes].join(' ').toLowerCase().includes(q));$('#peopleList').innerHTML=a.map(x=>'<article class="person"><h3>'+esc(x.name)+'</h3><span class="tag">'+esc(x.circle)+'</span><p>'+esc(x.relationship||'Person')+'<br>'+esc(x.phone||'')+'<br>'+esc(x.email||'')+'</p>'+(x.supportNotes?'<p class="support-note"><b>How I can help:</b> '+esc(x.supportNotes)+'</p>':'')+(x.lastCheckin?'<p class="support-note"><b>Last check-in:</b> '+esc(fmt(x.lastCheckin))+'</p>':'')+'<div class="quick-actions">'+actionButtons(x)+'</div><div class="actions"><button data-edit="person" data-id="'+x.id+'">Edit</button><button data-del="person" data-id="'+x.id+'">Delete</button></div></article>').join('');$('#peopleEmpty').hidden=a.length>0}
function renderDates(){const q=($('#datesSearch')?.value||'').toLowerCase(),t=$('#typeFilter')?.value||'',a=[...data.dates].filter(x=>(!t||x.type===t)&&[x.title,x.type,x.personName,x.notes].join(' ').toLowerCase().includes(q)).sort((a,b)=>a.date.localeCompare(b.date));$('#datesList').innerHTML=a.map(x=>'<article class="event"><div class="datebox"><b>'+(x.date?new Date(x.date+'T12:00:00').getDate():'—')+'</b><small>'+(x.date?esc(new Intl.DateTimeFormat(undefined,{month:'short'}).format(new Date(x.date+'T12:00:00'))):'DATE')+'</small></div><div class="rowcopy"><b>'+esc(x.title)+'</b><small>'+esc(x.type)+(x.personName?' · '+esc(x.personName):'')+' · '+esc(x.recurring?(days(x.date,true)===0?'Today':days(x.date,true)+' days away'):fmt(x.date))+(x.recurring?' · Yearly':'')+(x.notes?' · '+esc(x.notes):'')+'</small></div><div class="event-actions"><button data-edit="date" data-id="'+x.id+'">Edit</button><button data-del="date" data-id="'+x.id+'">Delete</button></div></article>').join('');$('#datesEmpty').hidden=a.length>0}
function renderReminders(){const q=($('#remindersSearch')?.value||'').toLowerCase(),f=$('#reminderFilter')?.value||'open',today=iso(),overdue=data.reminders.filter(x=>!x.done&&x.dueDate&&x.dueDate<today).length,dueToday=data.reminders.filter(x=>!x.done&&x.dueDate===today).length,upcoming=data.reminders.filter(x=>!x.done&&(!x.dueDate||x.dueDate>today)).length;if($('#reminderOverdueCount'))$('#reminderOverdueCount').textContent=overdue;if($('#reminderTodayCount'))$('#reminderTodayCount').textContent=dueToday;if($('#reminderUpcomingCount'))$('#reminderUpcomingCount').textContent=upcoming;const a=[...data.reminders].filter(x=>{const overdue=!x.done&&x.dueDate&&x.dueDate<today,isToday=!x.done&&x.dueDate===today,upcoming=!x.done&&(!x.dueDate||x.dueDate>today);return(f==='all'||(f==='done'?x.done:f==='overdue'?overdue:f==='today'?isToday:f==='upcoming'?upcoming:!x.done))&&[x.title,x.personName,x.notes].join(' ').toLowerCase().includes(q)}).sort((a,b)=>(a.done?1:0)-(b.done?1:0)||(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));$('#remindersList').innerHTML=a.map(x=>'<article class="event"><div class="datebox"><b>'+(x.done?'✓':'◇')+'</b><small>'+(x.done?'DONE':'TASK')+'</small></div><div class="rowcopy"><b class="'+(x.done?'strike':'')+'">'+esc(x.title)+'</b><small>'+(x.personName?esc(x.personName)+' · ':'')+(x.dueDate?'Due '+esc(fmt(x.dueDate)):'No due date')+(x.notes?' · '+esc(x.notes):'')+'</small></div><div class="event-actions">'+(x.done?'<button class="done" data-done="'+x.id+'">Reopen</button>':'<button class="done" data-done="'+x.id+'">Complete</button>')+'<button data-edit="reminder" data-id="'+x.id+'">Edit</button><button data-del="reminder" data-id="'+x.id+'">Delete</button></div></article>').join('');$('#remindersEmpty').hidden=a.length>0}
function renderMemories(){const q=($('#memoriesSearch')?.value||'').toLowerCase(),a=[...data.memories].filter(x=>[x.title,x.body,x.related,x.category].join(' ').toLowerCase().includes(q)).sort((a,b)=>(b.memoryDate||b.createdAt||'').localeCompare(a.memoryDate||a.createdAt||''));$('#memoriesList').innerHTML=a.map(x=>'<article class="memory"><small>'+esc(x.memoryDate?fmt(x.memoryDate):'UNDATED MEMORY')+'</small><h3>'+esc(x.title)+'</h3><span class="tag">'+esc(x.category||'General')+'</span><p>'+esc(x.body)+'</p>'+(x.related?'<span class="tag">'+esc(x.related)+'</span>':'')+'<div class="actions"><button data-edit="memory" data-id="'+x.id+'">Edit</button><button data-del="memory" data-id="'+x.id+'">Delete</button></div></article>').join('');$('#memoriesEmpty').hidden=a.length>0}
function renderCheckins(){const q=($('#checkinsSearch')?.value||'').toLowerCase(),f=$('#checkinFilter')?.value||'open',a=data.checkins.filter(x=>(f==='all'||(f==='done'?x.done:!x.done))&&[x.title,x.personName,x.notes,x.supportType].join(' ').toLowerCase().includes(q)).sort((a,b)=>(a.done?1:0)-(b.done?1:0)||(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));$('#checkinsList').innerHTML=a.map(x=>'<article class="event"><div class="datebox"><b>'+(x.done?'✓':'♡')+'</b><small>'+esc(x.supportType||'HELP')+'</small></div><div class="rowcopy"><b class="'+(x.done?'strike':'')+'">'+esc(x.title)+'</b><small>'+esc(x.personName||'Someone')+(x.dueDate?' · '+esc(fmt(x.dueDate)):'')+(x.notes?' · '+esc(x.notes):'')+'</small></div><div class="event-actions"><button class="done" data-checkdone="'+x.id+'">'+(x.done?'Reopen':'Complete')+'</button><button data-edit="checkin" data-id="'+x.id+'">Edit</button><button data-del="checkin" data-id="'+x.id+'">Delete</button></div></article>').join('');$('#checkinsEmpty').hidden=a.length>0}
function renderHelp(){const q=($('#helpSearch')?.value||'').toLowerCase(),a=data.helpCards.filter(x=>[x.title,x.body,x.category].join(' ').toLowerCase().includes(q));$('#helpList').innerHTML=a.map(x=>'<article class="memory"><span class="tag">'+esc(x.category)+'</span><h3>'+esc(x.title)+'</h3><p>'+esc(x.body)+'</p><div class="actions"><button data-edit="help" data-id="'+x.id+'">Edit</button><button data-del="help" data-id="'+x.id+'">Delete</button></div></article>').join('');$('#helpEmpty').hidden=a.length>0}
function renderProfile(){if(!$('#displayName'))return;$('#displayName').value=data.profile.name||'';$('#timezone').value=data.profile.timezone||'';$('#largeText').checked=!!data.profile.largeText;$('#highContrast').checked=!!data.profile.highContrast;$('#reducedMotion').checked=!!data.profile.reducedMotion;$('#simpleMode').checked=!!data.profile.simpleMode}function render(){applyPrefs();renderOverview();renderPeople();renderDates();renderReminders();renderMemories();renderCheckins();renderHelp();renderProfile();renderPhonebook();const opts=$('#peopleOptions');if(opts)opts.innerHTML=data.people.map(p=>'<option value="'+esc(p.name)+'"></option>').join('')}
function normalizePhone(v){return String(v||'').trim().replace(/[^\d+]/g,'').replace(/^00/,'+')}
function phoneDigits(v){return normalizePhone(v).replace(/\D/g,'')}function whatsappDigits(v){const n=phoneDigits(v);return n.length===10?'91'+n:n}
function renderPhonebook(){const box=$('#phonebookList');if(!box)return;const people=data.people.filter(x=>x.phone);box.innerHTML=people.length?'<label><input type="checkbox" id="phoneSelectAll"> Select all contacts</label>'+people.map(p=>'<label class="phonebook-row"><input type="checkbox" class="phone-select" value="'+esc(p.id)+'"><span><b>'+esc(p.name)+'</b><small>'+esc(p.phone)+'</small></span></label>').join(''):'<p>No saved phone numbers yet. Add people or import a VCF file.';const all=$('#phoneSelectAll');if(all)all.addEventListener('change',()=>$$('.phone-select').forEach(x=>x.checked=all.checked))}
function exportVcf(){const chosen=$$('.phone-select:checked').map(x=>data.people.find(p=>p.id===x.value)).filter(p=>p&&p.phone);if(!chosen.length){toast('Select at least one contact with a phone number.');return}const clean=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const cards=chosen.map(p=>'BEGIN:VCARD\r\nVERSION:3.0\r\nFN:'+clean(p.name)+'\r\nTEL;TYPE=CELL:'+normalizePhone(p.phone)+'\r\nEND:VCARD').join('\r\n');const blob=new Blob([cards+'\r\n'],{type:'text/vcard;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='aether-contacts.vcf';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exported '+chosen.length+' contact(s) to VCF.')}
async function importVcf(e){const file=e.target.files?.[0];if(!file)return;try{const raw=(await file.text()).replace(/\r\n[ \t]/g,'').replace(/\n[ \t]/g,'');const blocks=raw.match(/BEGIN:VCARD[\s\S]*?END:VCARD/gi)||[];let added=0;for(const block of blocks){let name='',phone='';for(const line of block.split(/\r?\n/)){if(/^FN(?:;[^:]*)?:/i.test(line))name=line.slice(line.indexOf(':')+1).trim();else if(/^TEL(?:;[^:]*)?:/i.test(line)&&!phone)phone=line.slice(line.indexOf(':')+1).trim()}phone=normalizePhone(phone);if(!name||!phone)continue;const old=data.people.find(p=>phoneDigits(p.phone)===phoneDigits(phone)||String(p.name||'').toLowerCase()===name.toLowerCase());if(old){if(!old.phone)old.phone=phone;continue}data.people.unshift({id:uid(),name,circle:'Other',relationship:'',phone,email:'',preferred:'Call',supportNotes:'',notes:'Imported from VCF',createdAt:new Date().toISOString()});added++}if(save()){render();toast('VCF import complete. Added '+added+' new contact(s).')}}catch(err){toast('Could not import VCF: '+err.message)}finally{e.target.value=''}}
function communicationCommand(s){let m,x;const t=String(s||'').trim();m=t.match(/^(?:whatsapp\s+video\s+call|video\s+call(?:\s+on\s+whatsapp)?)\s+(.+)$/i);if(m){x=findPerson(m[1]);if(!x)return'No matching saved contact found.';if(!x.phone)return x.name+' has no saved phone number.';window.open('https://wa.me/'+whatsappDigits(x.phone),'_blank','noopener');return'Opened '+x.name+'’s WhatsApp chat. Start the video call in WhatsApp.'}m=t.match(/^(?:call|phone|dial|ring)\s+(.+?)(?:\s+now)?$/i);if(m){x=findPerson(m[1]);if(!x)return'No matching saved contact found.';if(!x.phone)return x.name+' has no saved phone number.';location.href='tel:'+normalizePhone(x.phone);return'Handing off the call to your device for '+x.name+'.'}m=t.match(/^(?:whatsapp|message|msg|text|send\s+(?:a\s+)?message\s+to)\s+(.+?)(?:\s+(?:saying|that)\s+(.+))?$/i);if(m){x=findPerson(m[1]);if(!x)return'No matching saved contact found.';if(!x.phone)return x.name+' has no saved phone number.';window.open('https://wa.me/'+whatsappDigits(x.phone)+(m[2]?'?text='+encodeURIComponent(m[2]):''),'_blank','noopener');return'Opened WhatsApp using '+x.name+'’s saved phone number. Review and send there.'}return null}
function findPerson(q){return data.people.find(x=>String(x.name||'').trim().toLowerCase()===String(q||'').trim().toLowerCase())||data.people.find(x=>[x.name,x.phone,x.email].join(' ').toLowerCase().includes(String(q||'').toLowerCase()))}function openPersonAction(query,mode){const p=findPerson(query);if(!p)return'No matching person found. Add their contact details first.';if(mode==='call'&&p.phone){location.href='tel:'+normalizePhone(p.phone);return'Opening the phone/caller app.'}if((mode==='whatsapp'||mode==='message')&&p.phone){window.open('https://wa.me/'+whatsappDigits(p.phone),'_blank','noopener');return'Opening WhatsApp for '+p.name+'. Review the chat before sending.'}if(mode==='video'&&p.phone){window.open('https://wa.me/'+whatsappDigits(p.phone),'_blank','noopener');return'Opening WhatsApp chat for '+p.name+'. Start the video call from WhatsApp.'}if(mode==='email'&&p.email){location.href='mailto:'+p.email;return'Opening your email app.'}return'No usable contact method is saved for '+p.name+'.'}
function draftCommunication(){const p=findPerson($('#draftPerson').value.trim());if(!p){toast('Add or select a saved person first.');return}const text=$('#draftMessage').value.trim();if(!text){toast('Write a message first.');return}const channel=$('#draftChannel').value;if(channel==='WhatsApp'){if(!p.phone){toast('This person has no phone number saved.');return}window.open('https://wa.me/'+whatsappDigits(p.phone)+'?text='+encodeURIComponent(text),'_blank','noopener');toast('WhatsApp draft opened for review.')}else{if(!p.email){toast('This person has no email saved.');return}location.href='mailto:'+p.email+'?subject='+encodeURIComponent($('#draftSubject').value.trim()||'AETHER message')+'&body='+encodeURIComponent(text);toast('Email draft opened for review.')}}
function command(s){s=String(s||'').trim();let m;const comm=communicationCommand(s);if(comm)return comm;
if((m=s.match(/^(?:email|mail)\s+(.+?)(?:\s+(?:saying|with message)\s+(.+))?$/i))){const p=findPerson(m[1]);if(!p)return'No matching saved contact found.';if(!p.email)return p.name+' has no saved email address.';location.href='mailto:'+p.email+(m[2]?'?subject='+encodeURIComponent('AETHER message')+'&body='+encodeURIComponent(m[2]):'');return'Opened an email draft for '+p.name+'. Review it before sending.'}
if((m=s.match(/^(?:remind me|reminder|create reminder|add reminder)(?:\s+to)?\s+(.+)$/i))){let text=m[1].trim(),d='';if(/\btomorrow\b/i.test(text)){const t=new Date();t.setDate(t.getDate()+1);d=iso(t);text=text.replace(/\btomorrow\b/i,'').trim()}else if(/\btoday\b/i.test(text)){d=iso();text=text.replace(/\btoday\b/i,'').trim()}data.reminders.unshift({id:uid(),title:text||'Reminder',dueDate:d,personName:'',notes:'',done:false,createdAt:new Date().toISOString()});if(save()){render();return'Reminder saved locally'+(d?' for '+fmt(d):'')+'.'}return'Could not save the reminder.'}
if((m=s.match(/^(?:check in on|check-in with|follow up with)\s+(.+?)(?:\s+(today|tomorrow))?$/i))){const personName=m[1].trim();let d='';if(m[2]){const t=new Date();if(m[2].toLowerCase()==='tomorrow')t.setDate(t.getDate()+1);d=iso(t)}data.checkins.unshift({id:uid(),title:'Check in with '+personName,personName,dueDate:d,supportType:'Check in',notes:'Created by AETHER command',done:false,createdAt:new Date().toISOString()});if(save()){render();return'Added a support check-in for '+personName+'.'}return'Could not save the check-in.'}
if((m=s.match(/^(?:save|remember)(?:\s+(?:a\s+)?memory)?\s*:?\s+(.+)$/i))){const body=m[1].trim();data.memories.unshift({id:uid(),title:body.slice(0,80),body,category:'General',related:'',memoryDate:iso(),createdAt:new Date().toISOString()});if(save()){render();return'Memory saved in your local vault.'}return'Could not save the memory.'}
if(/^(?:show|open|list|go to|navigate to)\s+(?:my\s+)?(?:dashboard|home|overview)$/i.test(s)){view('overview');return'Opened the overview dashboard.'}
if(/^(?:show|open|list|go to|navigate to)\s+(?:my\s+)?(?:upcoming\s+)?(?:birthdays|important dates|dates|calendar)$/i.test(s)){view('dates');return'Opened important dates.'}
if(/^(?:show|open|list|go to|navigate to)\s+(?:my\s+)?(?:people|contacts|family|friends|circles)$/i.test(s)){view('people');return'Opened People & circles.'}
if(/^(?:show|open|list|go to|navigate to)\s+(?:my\s+)?(?:memories|memory vault)$/i.test(s)){view('memories');return'Opened Memory vault.'}
if(/^(?:show|open|list|go to|navigate to)\s+(?:my\s+)?(?:reminders|tasks|to-dos)$/i.test(s)){view('reminders');return'Opened reminders.'}
if(/^(?:show|open|list|go to|navigate to)\s+(?:my\s+)?(?:support|support hub|check-ins)$/i.test(s)){view('support');return'Opened Support Hub.'}
if(/^(?:show|open|list|go to|navigate to)\s+(?:my\s+)?(?:help cards|quick help|help)$/i.test(s)){view('help');return'Opened Help Cards.'}
if(/^(?:show|open|go to|navigate to)\s+(?:settings|privacy)$/i.test(s)){view('settings');return'Opened Settings & privacy.'}
if(/^(?:help|commands|what can you do)\??$/i.test(s))return'Try: call Jayant; WhatsApp Jayant saying hello; video call Jayant; email Jayant saying hello; remind me to call Dad tomorrow; check in on Asha tomorrow; save memory: family dinner; show support; open settings.';
if((m=s.match(/^(?:add|save) person\s*:\s*(.+)$/i))){editor('person');$('#fields [name="name"]').value=m[1];return'Person form opened. Review and save.'}
return'I could not match that command. Type “help” to see supported commands.'}
function exportBackup(){const b=new Blob([JSON.stringify({...data,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='aether-backup-'+iso()+'.json';a.click();URL.revokeObjectURL(u);toast('Backup export started.')}async function importBackup(e){const f=e.target.files?.[0];if(!f)return;try{const d=JSON.parse(await f.text());if(!d||!['people','dates','reminders','memories'].every(k=>Array.isArray(d[k])))throw Error('Backup format not recognized');if(!confirm('Importing replaces this local workspace. Continue?'))return;data={...blank(),...d,profile:{...blank().profile,...d.profile},checkins:Array.isArray(d.checkins)?d.checkins:[],helpCards:Array.isArray(d.helpCards)?d.helpCards:[]};for(const k of['people','dates','reminders','memories','checkins','helpCards'])data[k]=data[k].map(x=>({...x,id:String(x.id||uid())}));if(save()){render();toast('Backup imported.')}}catch(err){toast('Import failed: '+err.message)}finally{e.target.value=''}}function voice(){const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){toast('Voice input is not supported in this browser. Type a command instead.');return}const r=new R();r.lang=navigator.language||'en-US';r.maxAlternatives=3;r.interimResults=false;r.onresult=e=>{$('#command').value=e.results[0][0].transcript;$('#commandForm').requestSubmit()};r.onerror=()=>toast('Voice input was not available.');try{r.start();toast('Listening…')}catch{toast('Could not start voice input.')}}function shareSupport(){const text='AETHER Support Card\n\n'+data.helpCards.slice(0,3).map(x=>x.title+': '+x.body).join('\n\n');if(navigator.share){navigator.share({title:'AETHER Support',text}).then(()=>toast('Shared.')).catch(()=>{});}else if(navigator.clipboard){navigator.clipboard.writeText(text).then(()=>toast('Support card copied to clipboard.')).catch(()=>toast('Sharing is not available here.'))}else toast('Sharing is not available here.')}
document.addEventListener('click',e=>{const n=e.target.closest('[data-view]');if(n){view(n.dataset.view);return}const o=e.target.closest('[data-open]');if(o){view(o.dataset.open);return}const a=e.target.closest('[data-add]');if(a){editor(a.dataset.add);return}const ed=e.target.closest('[data-edit]');if(ed){editor(ed.dataset.edit,ed.dataset.id);return}const de=e.target.closest('[data-del]');if(de){del(de.dataset.del,de.dataset.id);return}const dn=e.target.closest('[data-done]');if(dn){complete('reminder',dn.dataset.done);return}const cd=e.target.closest('[data-checkdone]');if(cd){complete('checkin',cd.dataset.checkdone);return}if(e.target.id==='menu')$('#sidebar').classList.toggle('open');if(e.target.id==='close'||e.target.id==='cancel')close();if(e.target.id==='export')exportBackup();if(e.target.id==='exportVcf')exportVcf();if(e.target.id==='voice')voice();if(e.target.id==='shareSupport')shareSupport();if(e.target.id==='draftSend')draftCommunication()});
$('#editForm').addEventListener('submit',submit);$('#commandForm').addEventListener('submit',e=>{e.preventDefault();$('#feedback').textContent=command($('#command').value);$('#command').value=''});$('#profileForm').addEventListener('submit',e=>{e.preventDefault();data.profile.name=$('#displayName').value.trim();data.profile.timezone=$('#timezone').value.trim();if(save()){applyPrefs();toast('Profile saved.')}});$('#import').addEventListener('change',importBackup);$('#importVcf')?.addEventListener('change',importVcf);$('#clear').addEventListener('click',()=>{if(confirm('Clear all AETHER data saved in this browser? Export a backup first if needed.')){localStorage.removeItem(KEY);data=blank();render();toast('Local workspace cleared.')}});$('#draftSend').addEventListener('click',draftCommunication);$('#draftTemplate')?.addEventListener('change',e=>{const p=findPerson($('#draftPerson').value.trim()),name=p?.name||$('#draftPerson').value.trim()||'there',templates={checkin:'Hi '+name+', just checking in to see how you are doing. Is there anything I can help with?',offer:'Hi '+name+', I wanted to ask if there is anything I can do to support you this week.',birthday:'Wishing you a very happy birthday, '+name+'! Hope you have a wonderful day.',followup:'Hi '+name+', I wanted to follow up on our last conversation. Let me know when you have a moment.'};const value=templates[e.target.value];if(value){$('#draftMessage').value=value;if($('#draftChannel').value==='Email'&&!$('#draftSubject').value)$('#draftSubject').value=e.target.value==='birthday'?'Birthday wishes':'Just checking in';}});
['peopleSearch','circleFilter','datesSearch','typeFilter','remindersSearch','reminderFilter','memoriesSearch','checkinsSearch','checkinFilter','helpSearch'].forEach(id=>$('#'+id)?.addEventListener('input',render));['circleFilter','typeFilter','reminderFilter','checkinFilter'].forEach(id=>$('#'+id)?.addEventListener('change',render));['largeText','highContrast','reducedMotion','simpleMode'].forEach(id=>$('#'+id)?.addEventListener('change',e=>{data.profile[id]=e.target.checked;save();applyPrefs()}));render();
