$('#p7-memory').innerHTML=`<div class="p7-grid"><article class="p7-card"><small>MEMORY 2.0</small><h3>Capture a memory</h3><form id="p7MemoryForm" class="p7-form"><input name="title" required placeholder="Memory title"><textarea name="body" required placeholder="What should AETHER remember?"></textarea><select name="type"><option>episodic</option><option>semantic</option><option>preference</option><option>relationship</option><option>project</option><option>learning</option><option>event</option><option>decision</option><option>conversation</option><option>goal</option><option>historical</option></select><input name="tags" placeholder="Tags, comma-separated"><button class="primary">Remember</button></form></article><article class="p7-card"><small>MEMORY INTELLIGENCE</small><h3>Organize & protect</h3><div id="p7MemoryTools"></div><button class="secondary" id="p7MemoryScan">Find duplicates / contradictions</button><button class="secondary" id="p7MemoryForget">Show forgetting candidates</button></article><div class="p7-card p7-wide"><small>MEMORY TIMELINE</small><div id="p7MemoryList"></div></div></div>`;
$('#p7-search').innerHTML=`<article class="p7-card"><small>UNIVERSAL INTELLIGENCE SEARCH</small><h3>Search the AETHER world</h3><p>People, memories, projects, documents, tasks, events, goals, decisions and knowledge appear together.</p><form id="p7SearchForm" class="p7-search"><input id="p7SearchQ" placeholder="Search anything…"><select id="p7SearchKind"><option value="">Everything</option>${TYPES.map(x=>`<option>${x}</option>`).join('')}</select><button class="primary">Search</button></form><div id="p7SearchResults"></div></article>`;
